import re

from taf.ue.android.data_transfer.iperf.direction_specific.abstract_iperf_endpoint import AbstractIperfEndpoint


class AppServerIperfEndpoint(AbstractIperfEndpoint):

    def __init__(self, endpoint_access, dt_name, dt_config):
        super().__init__(endpoint_access, dt_name, dt_config)
        self.ip = self.dt_config['app_server']['address']
        self.iperf_reader = None
        self.iperf_binary = 'iperf' if str(self.dt_config['version']) == "2" else f"iperf{self.dt_config['version']}"

    def get_ip(self):
        return self.ip

    def get_bind_ip(self):
        return self.dt_config['app_server'].get('bind_interface_ip')

    def start_iperf(self, cmd):
        self.logger.debug(f'Starting iperf data transfer on App Server: ip={self.ip}, cmd={cmd}')
        self.iperf_reader = self.endpoint_access.run_cmd_and_get_non_blocking_reader(cmd=cmd, hostname=self.ip)

    def kill_iperf(self):
        check_msg = 'killok'
        kill_cmd = 'pkill -{signal} -P {pid} && echo {check_msg}'
        if self.iperf_reader:
            self.logger.debug(f'Killing iperf by pid on App Server: ip={self.ip}, pid={self.iperf_reader.pid}')
            output = self.endpoint_access.run_cmd_and_get_output_lines(
                cmd=kill_cmd.format(signal=9, pid=self.iperf_reader.pid, check_msg=check_msg),
                hostname=self.ip, as_string=True)
            if output and check_msg in output:
                self.logger.debug(f"Iperf process was successfully killed on App Server: {output}")
            else:
                self.logger.debug(
                    f"pid={self.iperf_reader.pid} has no child processes. "
                    "Seems like iperf was already stopped."
                )
            self.iperf_reader.close()
        else:
            self.logger.debug(f"No iperf reader found for App Server: ip={self.ip}")
        self.logger.debug(f'Closing paramiko connection to App Server: ip={self.ip}')

    def is_iperf_running(self):
        """
        Returns true if cmd is still running and has no exit status
        Returns false if cmd finished and exit status is available
        """
        if self.iperf_reader:
            return not self.iperf_reader.chan.exit_status_ready() and not self.iperf_reader.is_finish()
        return False

    def read_iperf_output(self):
        return self.iperf_reader.read_lines()

    def get_iperf_path(self):
        return self.iperf_binary

    def list_occupied_ports_on_device(self):
        self.logger.debug(f'{repr(self)}: running netstat command: {self.NETSTAT_OCCUPIED_PORTS_CMD}')
        netstat_output = self.endpoint_access.run_cmd_and_get_output_lines(cmd=self.NETSTAT_OCCUPIED_PORTS_CMD,
                                                                           hostname=self.ip)
        if not netstat_output:
            self.logger.debug(f'{repr(self)}: output is empty! Repeating netstat command in pseudo-terminal.')
            netstat_output = self.endpoint_access.run_cmd_and_get_output_lines(cmd=self.NETSTAT_OCCUPIED_PORTS_CMD,
                                                                               hostname=self.ip, get_pty=True)
        self.logger.debug(f'{repr(self)}: netstat output:\n{netstat_output}')
        return netstat_output

    def get_app_server_iperf_version(self):
        """
        Detects and logs the iPerf version running on the application server.
        Logs an error message if the version cannot be determined or a failure occurs.
        """
        iperf_pattern = r'[23]\.[0-9]+(\.[0-9]+)?'
        cmd = self.iperf_binary + " --version"
        try:
            iperf_version_line = self.endpoint_access.run_cmd_and_get_output_lines(cmd=cmd, hostname=self.ip,
                                                                                   as_string=True, get_pty=True)
            iperf_version_search = re.search(iperf_pattern, iperf_version_line)
            if iperf_version_search:
                log_line = f"iperf version detected on APP SERVER: {iperf_version_search.group()}"
            else:
                log_line = "Cannot detect iperf version on APP SERVER"
        except Exception as e:
            log_line = f"Error while detecting iperf version on APP SERVER: {e}"
        self.logger.debug(log_line)


